GRANT UPDATE(city) ON public.profiles TO authenticated;
CREATE OR REPLACE FUNCTION public.complete_invitation(invite_token text, claim uuid, uid uuid, fields jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.invitations WHERE token=invite_token AND claim_id=claim AND used_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Invalid invitation'; END IF; UPDATE public.profiles SET email=fields->>'email',first_name=fields->>'first_name',last_name=fields->>'last_name',linkedin_url=fields->>'linkedin_url',job_title=fields->>'job_title',company=fields->>'company',city=fields->>'city',company_size=fields->>'company_size',sector=fields->>'sector',job_tags=ARRAY(SELECT jsonb_array_elements_text(fields->'job_tags')),intentions=ARRAY(SELECT jsonb_array_elements_text(fields->'intentions')),pitch=fields->>'pitch',ai_level=fields->>'ai_level',lang=fields->>'lang',consent_at=now() WHERE user_id=uid; IF NOT FOUND THEN RAISE EXCEPTION 'Missing profile'; END IF; UPDATE public.invitations SET used_at=now(),claim_id=NULL,claimed_at=NULL WHERE token=invite_token; END $$;
REVOKE ALL ON FUNCTION public.complete_invitation(text,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_invitation(text,uuid,uuid,jsonb) TO service_role;